// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        // Restrict to admissible values: MinSum is 1 ether, ensure deposit >= 1 ether and collectAmount <= depositAmount
        // and actor is not address(this) or the C contract itself, and actor has no existing balance.
        vm.assume(actor != address(this) && actor != address(c));
        vm.assume(depositAmount >= 1 ether && depositAmount <= 100 ether);
        vm.assume(collectAmount >= 1 ether && collectAmount <= depositAmount);

        // Initialize contract and set up initial state
        c.Initialized();

        // Fund actor and make deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Record balance before collect
        uint256 balanceBefore = c.balances(actor);

        // Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        // Balance after collect
        uint256 balanceAfter = c.balances(actor);

        // Rule: If the deposit worked (balanceBefore > 0), then balanceAfter must be balanceBefore - collectAmount
        // In the buggy version, balanceBefore is 0 (or whatever was before) because deposit doesn't increase it,
        // so either Collect reverts, or balanceAfter is not balanceBefore - collectAmount.
        // More precisely: if Collect didn't revert, the balance after should be exactly balanceBefore - collectAmount.
        // We check this via a try/catch to handle the revert case.
        bool ok;
        try c.Collect(collectAmount) {
            // If we already called Collect above, we can't call again; instead we restructure:
            // We'll do the try/catch in the same call, but we need to assert on the balance change.
            // Since we already called Collect above, we can simply assert on the final balance.
            // But the rule must hold for ANY Collect call. We'll make a fresh call in a try.
        } catch {}

        // Simpler: after the Collect, the balance must be exactly balanceBefore - collectAmount
        // In reference: balanceBefore = depositAmount (since deposit worked), so balanceAfter = depositAmount - collectAmount.
        // In buggy: balanceBefore = 0 (if actor had no prior balance), so Collect either reverts (if balanceBefore < MinSum)
        // or if it doesn't revert, balanceAfter would be 0 - collectAmount (underflow) or something else.
        // To cover both, we assert that if the Collect call didn't revert,
        // then balanceAfter == balanceBefore - collectAmount.
        // We'll use a flag to detect revert from the previous call.
        // The fuzzer will find a case where the buggy version has balanceBefore=0 (or small) and the assertion fails.

        // Actually, we can assert: (balanceBefore >= c.MinSum() && balanceBefore >= collectAmount) ?
        //   (balanceAfter == balanceBefore - collectAmount) : true;
        // This holds for reference, but for buggy: if balanceBefore is 0 (or small) but somehow Collect didn't revert
        // (in the buggy, balanceBefore might be >0 from a previous direct transfer, but we don't have that),
        // then it fails.
        // However, the buggy version's Deposit doesn't increase balance, so balanceBefore is 0 (if actor had no prior balance).
        // Then balanceBefore < MinSum (1 ether), so Collect reverts. So we need to trigger a scenario where Collect doesn't revert
        // in the buggy version, or where balanceBefore is >0 but not from Deposit.
        // The mutation only changes Deposit; other ways to increase balance? No. So we need to give the actor some balance
        // without Deposit, or we need to check after a successful Collect that the balance decreased correctly.
        // But in the reference, after a successful Collect, balance decreases by exactly collectAmount.
        // In the buggy, if we can make Collect succeed, balanceBefore might be 0 (since Deposit did nothing),
        // so balanceAfter would be 0 - collectAmount (underflow? no, it would revert due to underflow in 0.8).
        // So Collect would always revert. Thus the difference might be that in the reference, Collect succeeds
        // and in the buggy, Collect reverts. That's a behavioral difference we can catch with try/catch.

        // Better approach: Assert that after Deposit, the balance increased by depositAmount.
        // In reference: true; in buggy: false. Then we can assert on the balance increment.
        // But the problem states: "Driven through the public/external entry `Collect(uint256)`" and
        // "after a call to `Collect(...)` completes, the value of `balances` differs at some key k".
        // So we must make a Collect call and then check balances.

        // Let's restructure: We'll call Deposit, then immediately call Collect and check if it didn't revert,
        // then the final balance of the actor is exactly depositAmount - collectAmount.
        // If it did revert, then the balance of the actor should be depositAmount (since Collect didn't execute).
        // In buggy, after Deposit, balance is 0; Collect will revert because 0 < 1 ether (MinSum),
        // so balance stays 0. In reference, Collect succeeds and balance becomes depositAmount - collectAmount.
        // The assertion: if Collect reverts, then balance == depositAmount; if it doesn't revert, balance == depositAmount - collectAmount.
        // But the buggy version's Collect reverts and balance is 0, so the "if reverts" branch fails because balance (0) != depositAmount (which is >=1 ether).
        // So we can assert exactly that.

        // Implementation:
        uint256 balanceAfterDeposit = c.balances(actor);

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint256 balanceFinal = c.balances(actor);

        if (collectReverted) {
            assertEq(balanceFinal, balanceAfterDeposit, "After reverted Collect, balance should be unchanged");
        } else {
            assertEq(balanceFinal, balanceAfterDeposit - collectAmount, "After successful Collect, balance should decrease by collectAmount");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // 1. keep the domain wide: actor must not be C itself, and amount must not overflow balance mapping to avoid revert on require
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        // 2. record balance before deposit
        uint256 balanceBefore = c.balances(actor);
        // 3. give actor ether and deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // 4. general rule: the actor's balance must equal prior balance plus deposited amount
        assertTrue(c.balances(actor) == balanceBefore + amount);
    }
}

