pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.Initialized();
    }

    function testFuzz_property(
        address actor,
        uint256 depositAmount,
        uint256 collectAmount
    ) public {
        // Keep amounts reasonable and escape zero-address
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        depositAmount = bound(depositAmount, 1, 1000 ether);
        collectAmount = bound(collectAmount, 1, 1000 ether);

        // Give actor some ETH for the deposit and to cover gas
        vm.deal(actor, depositAmount + 1 ether);

        // Actor deposits via Deposit (not using the payable fallback to keep it explicit)
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Ensure MinSum is low enough that deposit can satisfy it for the test
        vm.prank(address(this));
        c.SetMinSum(0);

        uint256 balanceBefore = c.balances(actor);
        require(balanceBefore >= collectAmount, "setup: insufficient balance for collect");

        // Actor collects
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.balances(actor);

        // Reference: balanceAfter == balanceBefore - collectAmount
        // Bug (missing balance increment on deposit): balanceAfter == 0 (since deposit was never recorded, balance is 0 minus collectAmount underflow in original, but require in Collect only checks if balances[msg.sender]>=MinSum and >=_am, and if balances[msg.sender] is 0, the if block never executes, so balance stays 0. Actually in the reference, deposit increases balance, so after collect balance decreases. In the bug, deposit never records balance, so balance remains 0, Collect's if condition fails (0 >= 0 && 0 >= collectAmount is false for collectAmount > 0), so balance stays 0. So the invariant: if deposit succeeds and balanceBefore >= collectAmount, then after collect balance should be balanceBefore - collectAmount. In the bug, balanceBefore is 0, collect fails silently, balanceAfter is 0, so invariant 0 == 0 - x is false.
        assertTrue(balanceAfter == balanceBefore - collectAmount);
    }
}

