pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 seedDeposit, uint256 seedCollect) public {
        vm.assume(actor != address(0));
        vm.assume(seedDeposit >= 1 ether);
        vm.assume(seedCollect <= seedDeposit);
        vm.deal(actor, seedDeposit);
        vm.prank(actor);
        c.Deposit{value: seedDeposit}();
        uint256 balBefore = c.balances(actor);
        uint256 collectorBalanceBefore = actor.balance;
        vm.prank(actor);
        try c.Collect(seedCollect) {
            uint256 balAfter = c.balances(actor);
            uint256 collectorBalanceAfter = actor.balance;
            assertEq(balAfter + (collectorBalanceAfter - collectorBalanceBefore), balBefore);
        } catch {
            uint256 balAfter = c.balances(actor);
            assertEq(balAfter, balBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint amt1, uint amt2) public payable {
        require(amt1 > 0 && amt2 > 0);
        require(address(this).balance >= amt1 + amt2);
        c.Deposit{value: amt1}();
        uint balBefore = c.balances(address(this));
        c.Deposit{value: amt2}();
        uint balAfter = c.balances(address(this));
        assert(balAfter >= balBefore + amt2);
    }
}
